package dev.kelmagic.artifact;
import dev.kelmagic.server.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import java.util.List;
public final class ArtifactWeapon extends SwordItem {
    public final String artifact;
    public ArtifactWeapon(String id,Properties p){super(Tiers.DIAMOND,p);artifact=id;}
    @Override public void appendHoverText(ItemStack s,Item.TooltipContext c,List<Component> lines,TooltipFlag f){lines.add(Component.translatable("kelmagic.artifact.tip."+artifact));if(artifact.equals("unspoken_dagger"))lines.add(Component.translatable("kelmagic.artifact.dagger_charge",ArtifactData.charge(s,100)));}
    @Override public int getUseDuration(ItemStack s,LivingEntity e){return artifact.equals("mute_verdict_hammer")?72000:0;}
    @Override public UseAnim getUseAnimation(ItemStack s){return artifact.equals("mute_verdict_hammer")?UseAnim.SPEAR:UseAnim.NONE;}
    @Override public void releaseUsing(ItemStack stack,Level l,LivingEntity e,int left){if(e instanceof ServerPlayer p&&artifact.equals("mute_verdict_hammer")&&getUseDuration(stack,e)-left>=20&&ArtifactRuntime.spend(p,2)){p.getPersistentData().putLong("KelHammerChargedUntil",l.getGameTime()+60);ArtifactVisuals.sound(p.serverLevel(),p.position(),"silence_fall",.8f);}}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player player,InteractionHand hand){var stack=player.getItemInHand(hand);if(!(player instanceof ServerPlayer p))return InteractionResultHolder.pass(stack);if(p.getCooldowns().isOnCooldown(this)||p.isSpectator()||!ArtifactRuntime.canCast(p))return InteractionResultHolder.fail(stack);
        switch(artifact){case "mute_verdict_hammer"->{p.startUsingItem(hand);return InteractionResultHolder.consume(stack);}case "short_threshold_spear"->{var target=ArtifactCombat.ray(p,7.5,false);if(target==null||!ArtifactRuntime.canHarm(p,target)||!ArtifactRuntime.spend(p,1))return InteractionResultHolder.fail(stack);if(target.hurt(p.damageSources().playerAttack(p),7)){ArtifactVisuals.line(p.serverLevel(),p.getEyePosition(),target.getBoundingBox().getCenter(),0xb99be9);p.getCooldowns().addCooldown(this,25);stack.hurtAndBreak(1,p,LivingEntity.getSlotForHand(hand));}return InteractionResultHolder.success(stack);}case "unspoken_dagger"->{var session=p.getData(MagicAttachments.SESSION);if(ArtifactData.charge(stack,100)>0||!session.active()||dev.kelmagic.core.SpellParser.plan(session.words()).effect()==dev.kelmagic.core.SpellParser.Effect.GRAND)return InteractionResultHolder.fail(stack);double paid=ArtifactRuntime.state(p).paid;if(paid<=0)return InteractionResultHolder.fail(stack);ArtifactData.charge(stack,Math.min(24,paid),100);MagicServer.action(p,new dev.kelmagic.network.SpellAction(session.generation(),session.revision(),true));p.getCooldowns().addCooldown(this,20);return InteractionResultHolder.success(stack);}case "shared_oath_sword"->{var target=ArtifactCombat.ray(p,6,true);if(target==null||!p.isAlliedTo(target))return InteractionResultHolder.fail(stack);p.getPersistentData().putUUID("KelOathTarget",target.getUUID());p.getPersistentData().putLong("KelOathUntil",l.getGameTime()+400);ArtifactVisuals.line(p.serverLevel(),p.position().add(0,1,0),target.position().add(0,1,0),0xeacb7a);return InteractionResultHolder.success(stack);}default->{return InteractionResultHolder.pass(stack);}}
    }
    @Override public boolean hurtEnemy(ItemStack stack,LivingEntity target,LivingEntity attacker){if(attacker instanceof ServerPlayer p&&ArtifactRuntime.canHarm(p,target)&&ArtifactRuntime.canCast(p)){long now=p.serverLevel().getGameTime();switch(artifact){case "precise_name_rapier"->{target.getPersistentData().putUUID("KelRapierOwner",p.getUUID());target.getPersistentData().putLong("KelRapierMark",now+100);p.getPersistentData().putLong("KelRapierUntil",now+100);}case "mute_verdict_hammer"->{if(p.getPersistentData().getLong("KelHammerChargedUntil")>now){target.getPersistentData().putLong("KelMuteUntil",now+40);p.getPersistentData().remove("KelHammerChargedUntil");ArtifactVisuals.ring(p.serverLevel(),target.position().add(0,.8,0),.65,0xb28ce4,18);}}case "living_fiber_whip"->ArtifactCombat.root(target,p,60);case "heavy_thought_mace"->{target.getPersistentData().putLong("KelHeavyUntil",now+60);target.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,60,1));}case "unspoken_dagger"->{double charge=ArtifactData.charge(stack,100);if(charge>0){ArtifactData.charge(stack,0,100);float extra=(float)Math.min(10,charge*.4);target.invulnerableTime=0;target.hurt(p.damageSources().playerAttack(p),extra);ArtifactVisuals.sound(p.serverLevel(),target.position(),"artifact_chime",.7f);}}default->{}}}return super.hurtEnemy(stack,target,attacker);}
}
